现在访问肯定都不是通过/index.html的方式。# ============================================================
# nginx.conf  —  Windows 版专用修正版 v3（已修复 ssl_handshake_timeout 报错）
# 适用：nginx-1.30.4 / Windows Server
# 修复记录：v2 中误用了 stream 模块指令 ssl_handshake_timeout，
#           HTTP 块不支持，已移除，改用 client_header_timeout 控制握手阶段。
# ============================================================

# Windows：官方明确说明 "Although several workers can be started,
# only one of them actually does any work."  写 8 只是白占内存和调度开销。
worker_processes  1;

error_log  D:/www/logs/error.log  error;
#pid        logs/nginx.pid;

events {
    # Windows 官方二进制 FD_SETSIZE=1024 是【编译期硬上限】。
    # 写 4096 不仅不生效，还会让 nginx 超额分配连接槽，
    # 结果是大量连接抢不进 select() 位图 —— 就是你日志里那串报错。
    worker_connections  1024;

    accept_mutex  on;
    multi_accept  off;
}

http {
    include       mime.types;
    default_type  application/octet-stream;

    log_format  main  '$remote_addr - $remote_user [$time_local] "$request" '
                      '$status $body_bytes_sent "$http_referer" '
                      '"$http_user_agent" "$http_x_forwarded_for"'
                      ' rt=$request_time urt=$upstream_response_time';

    # 加 buffer + flush，避免每个请求一次同步写盘。
    # Windows 下无缓冲 access_log 在高并发时是隐形 CPU/IO 杀手。
    access_log  D:/www/logs/access.log  main  buffer=256k  flush=5s;

    # Windows 版 sendfile 有已知缺陷，必须 off
    sendfile        off;
    tcp_nodelay     on;
    server_tokens   off;

    # ---------------------------------------------------------
    # 一、超时全线收紧 —— fd 是稀缺资源，绝不让连接"干等"
    # ---------------------------------------------------------

    # 【最重要】HTTP 块里没有 ssl_handshake_timeout（那是 stream 模块的）。
    # nginx 在 HTTP 的 TLS 握手阶段，读定时器用的就是 client_header_timeout
    # （内部经 post_accept_timeout 传递，默认 60s）。
    # 所以它同时管两件事：握手不完成 + 请求头不发完，都在这里掐断。
    client_header_timeout     10s;
    client_body_timeout       15s;
    send_timeout              15s;

    keepalive_timeout         15s;    # 原 65s 太长，空闲连接白占 fd
    keepalive_requests        100;
    reset_timedout_connection on;     # 超时直接 RST，不等四次挥手

    # 复用 TLS 会话，大幅减少重复握手（省 CPU 也省 fd 占用时长）
    # [表情] ssl_session_cache 不要在这里写：你的 443.conf 里已经声明了
    #    shared:SSL:10m，同名 zone 在两级声明且 size 不同会直接 emerg 冲突。
    #    这里只放不会冲突的指令。
    ssl_session_timeout       10m;
    ssl_session_tickets       off;
    ssl_prefer_server_ciphers on;

    # ---------------------------------------------------------
    # 二、限流 —— 注意：zone 定义了必须在 server/location 里引用才生效
    # ---------------------------------------------------------
    # IP 白名单：命中白名单的 IP 返回空 key，limit_req/limit_conn 会自动跳过
    geo $white_ip {
        default        $binary_remote_addr;
        10.0.0.0/8     "";
        192.168.0.0/16 "";
        58.210.212.234 "";
        58.209.187.182 "";
        117.82.91.230  "";
        117.81.113.46  "";
        223.104.153.67 "";
        49.75.54.12    "";
    }

    # 【静态资源豁免】nginx 官方没有 limit_req off;（那是 Tengine 语法）。
    # 官方支持的豁免方式：让 key 为空 —— "requests with an empty key value
    # are not accounted"。default 沿用 $white_ip，两个豁免规则叠加生效。
    map $request_uri $limit_key {
        default  $white_ip;
        ~*\.(js|mjs|css|png|jpg|jpeg|gif|ico|svg|webp|bmp|woff|woff2|ttf|eot|otf|mp4|webm|mp3|pdf)(\?|$)  "";
    }

    # ---------------------------------------------------------
    # 三、安全头（保持原逻辑不变）
    # ---------------------------------------------------------
    map $request_uri $is_pdf {
        default    0;
        ~*\.pdf    1;
    }

    map $is_pdf $csp_policy {
        default "default-src 'self'; script-src 'self' 'unsafe-eval' 'unsafe-inline' https://sipps.sipac.gov.cn  https://*.map.qq.com  https://*.qq.com  https://*.qpic.cn data: blob:; connect-src 'self'  https://*.map.qq.com  https://*.gtimg.com  https://*.qq.com  https://*.qpic.cn  https://ssl.map.qq.com wss://*.map.qq.com; img-src 'self' data:  https://*.qq.com  https://*.map.qq.com  https://*.gtimg.com  https://*.qpic.cn blob:; style-src 'self' 'unsafe-inline'; font-src 'self' data:; object-src 'none'; base-uri 'self'; form-action 'self'; frame-ancestors 'none';";
        1       "default-src 'self' blob:; script-src 'self' blob:; object-src 'self' blob:; style-src 'self' 'unsafe-inline'; img-src 'self' data: blob:; font-src 'self' data:; worker-src 'self' blob:; connect-src 'self'; base-uri 'none'; form-action 'none';";
    }

    map $is_pdf $x_frame_options { default "SAMEORIGIN"; 1 ""; }
    map $is_pdf $nosniff_policy  { default "nosniff";    1 ""; }

    # ---------------------------------------------------------
    # 四、反代默认值 —— 集中在 http 级，conf.d 里不必重复写
    # ---------------------------------------------------------
    # upstream 里的 keepalive 必须配这两行才生效，
    # 否则每个请求都新建一条到后端的连接 = fd 直接翻倍。
    proxy_http_version          1.1;
    proxy_set_header            Connection "";

    proxy_set_header            Host              $host;
    proxy_set_header            X-Real-IP         $remote_addr;
    proxy_set_header            X-Forwarded-For   $proxy_add_x_forwarded_for;
    proxy_set_header            X-Forwarded-Proto $scheme;

    # 原来 server 级是 600s，任何一次后端抖动 nginx 都傻等 10 分钟才放 fd。
    proxy_connect_timeout       5s;
    proxy_send_timeout          60s;
    proxy_read_timeout          120s;

    proxy_buffering             on;
    proxy_buffer_size           16k;
    proxy_buffers               8 16k;
    proxy_busy_buffers_size     32k;

    proxy_next_upstream         error timeout http_502 http_503 http_504;
    proxy_next_upstream_tries   2;
    proxy_next_upstream_timeout 10s;

    # ---------------------------------------------------------
    # 五、upstream
    # ---------------------------------------------------------
    upstream sipps-g {
        server 127.0.0.1:5081 weight=2 max_fails=5 fail_timeout=10s;
        keepalive           64;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    upstream sipps-app-api {
        server 172.24.96.6:9980 weight=5 max_fails=2 fail_timeout=10s;
        server 172.24.96.6:9981 weight=5 max_fails=2 fail_timeout=10s;
        keepalive           32;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # 172.24.96.2:880（benefit-test / nacos / grafana）
    upstream be_880 {
        server 172.24.96.2:880 max_fails=3 fail_timeout=10s;
        keepalive           16;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # 172.24.96.2:881（kaoping-test）
    upstream be_881 {
        server 172.24.96.2:881 max_fails=3 fail_timeout=10s;
        keepalive           8;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # 172.24.96.2:882（homeland-test）
    upstream be_882 {
        server 172.24.96.2:882 max_fails=3 fail_timeout=10s;
        keepalive           8;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # 172.24.96.2:80（wyglyq_dmp 数据库日志下载）
    upstream be_80 {
        server 172.24.96.2:80 max_fails=3 fail_timeout=10s;
        keepalive           4;
        keepalive_timeout   30s;
    }

    # 172.24.96.4:8899（api / prod-api / kpzxt / mgdcpc / txzh5 / bjresultquery）
    upstream be_8899 {
        server 172.24.96.4:8899 max_fails=3 fail_timeout=10s;
        keepalive           32;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # 172.24.96.4:8080（swagger 拦截用的 404 页）
    upstream be_8080 {
        server 172.24.96.4:8080 max_fails=3 fail_timeout=10s;
        keepalive           4;
        keepalive_timeout   30s;
    }

    # 172.24.96.6:10001（wechatapph5）
    upstream be_10001 {
        server 172.24.96.6:10001 max_fails=3 fail_timeout=10s;
        keepalive           16;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # 172.24.96.6:18666（app-test）
    upstream be_18666 {
        server 172.24.96.6:18666 max_fails=3 fail_timeout=10s;
        keepalive           8;
        keepalive_timeout   30s;
    }

    # 172.24.96.7:8092（ls）
    upstream be_8092 {
        server 172.24.96.7:8092 max_fails=3 fail_timeout=10s;
        keepalive           8;
        keepalive_timeout   30s;
    }

    # 172.24.96.5:5081（questH5）
    upstream be_5081 {
        server 172.24.96.5:5081 max_fails=3 fail_timeout=10s;
        keepalive           8;
        keepalive_timeout   30s;
    }

    # 172.24.96.3:8961（testabc）
    upstream be_8961 {
        server 172.24.96.3:8961 max_fails=3 fail_timeout=10s;
        keepalive           4;
        keepalive_timeout   30s;
    }

    # 172.24.96.3:8892（ams 埋点）
    upstream be_8892 {
        server 172.24.96.3:8892 max_fails=3 fail_timeout=10s;
        keepalive           16;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # 172.24.96.2:18080（9580 端口：园区公共收益生产环境-胜浦街道试点）
    upstream be_18080 {
        server 172.24.96.2:18080 max_fails=3 fail_timeout=10s;
        keepalive           32;
        keepalive_requests  1000;
        keepalive_timeout   30s;
    }

    # ---------------------------------------------------------
    # 六、错误页
    # 说明：原来这里有个 limit_conn_zone $binary_remote_addr zone=perip:10m;
    #      它和上面的 conn_zone 都是按单 IP 计数，功能完全重复。
    #      而且 perip 用 $binary_remote_addr 做 key，白名单 IP 不会被豁免，
    #      反而不如 conn_zone（用 $white_ip，白名单自动跳过）。
    #      已删除 perip，全文统一只用 conn_zone —— 顺便杜绝 zone 重复声明报错。
    # ---------------------------------------------------------
    error_page 500 501 502 503 504 = /50x.html;
	#error_page 404 D:/www/html/404.html;

    include D:/www/conf.d/*.conf;
}

